CREATE POLICY "Voice admin can add welcome photos" ON public.welcome_photos FOR INSERT TO authenticated WITH CHECK (public.has_role(auth.uid(), 'admin') AND (auth.jwt() ->> 'email') = 'khadri1982@gmail.com');
CREATE POLICY "Voice admin can reorder welcome photos" ON public.welcome_photos FOR UPDATE TO authenticated USING (public.has_role(auth.uid(), 'admin') AND (auth.jwt() ->> 'email') = 'khadri1982@gmail.com') WITH CHECK (public.has_role(auth.uid(), 'admin') AND (auth.jwt() ->> 'email') = 'khadri1982@gmail.com');
CREATE POLICY "Voice admin can delete welcome photos" ON public.welcome_photos FOR DELETE TO authenticated USING (public.has_role(auth.uid(), 'admin') AND (auth.jwt() ->> 'email') = 'khadri1982@gmail.com');
CREATE POLICY "Voice admin can upload welcome images" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'welcome-photos' AND public.has_role(auth.uid(), 'admin') AND (auth.jwt() ->> 'email') = 'khadri1982@gmail.com');
CREATE POLICY "Voice admin can remove welcome images" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'welcome-photos' AND public.has_role(auth.uid(), 'admin') AND (auth.jwt() ->> 'email') = 'khadri1982@gmail.com');